<template>
  <div class="space-y-4">
    <div class="flex items-center justify-between">
      <h3 class="text-sm font-semibold text-gray-800">课程作业</h3>
      <span class="text-xs text-gray-400">{{ submittedCount }}/{{ homeworks.length }} 已提交</span>
    </div>

    <!-- 作业列表 -->
    <div v-if="!answeringHomework" class="space-y-3">
      <div v-for="hw in homeworks" :key="hw.id"
        class="p-4 rounded-lg border border-gray-100 hover:bg-gray-50 transition-colors">
        <div class="flex items-start justify-between">
          <div class="flex-1">
            <p class="text-sm font-medium text-gray-900">{{ hw.title }}</p>
            <p v-if="hw.chapterTitle" class="text-xs text-gray-400 mt-0.5">{{ hw.chapterTitle }}</p>
            <p v-if="hw.description" class="text-xs text-gray-500 mt-1">{{ hw.description }}</p>
          </div>
          <div class="flex items-center gap-2 flex-shrink-0 ml-3">
            <!-- 未提交 -->
            <span v-if="!hw.submission" class="px-2 py-1 text-xs font-medium text-blue-600 bg-blue-50 rounded-full">未提交</span>
            <!-- 已批改 -->
            <span v-else-if="hw.submission.status === 'graded'"
              class="px-2 py-1 text-xs font-medium rounded-full"
              :class="getScoreClass(hw.submission.totalScore)">
              {{ hw.submission.totalScore }}分
            </span>
            <span v-else-if="hw.submission.status === 'submitted'"
              class="px-2 py-1 text-xs font-medium text-rose-600 bg-rose-50 rounded-full">
              待重试
            </span>
            <!-- 批改中 -->
            <span v-else class="px-2 py-1 text-xs font-medium text-amber-600 bg-amber-50 rounded-full">批改中</span>
          </div>
        </div>

        <div class="mt-3 flex items-center gap-3">
          <!-- 未提交：去做题 -->
          <button v-if="!hw.submission" @click="startAnswer(hw)"
            class="px-4 py-1.5 text-xs font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg transition-colors">
            开始作答
          </button>
          <!-- 已批改：查看结果 -->
          <button v-else-if="hw.submission.status === 'graded'" @click="viewResult(hw)"
            class="px-4 py-1.5 text-xs font-medium text-emerald-600 bg-emerald-50 hover:bg-emerald-100 rounded-lg transition-colors">
            查看结果
          </button>
          <button v-else-if="hw.submission.status === 'submitted'" @click="retryAnswer(hw)"
            class="px-4 py-1.5 text-xs font-medium text-rose-600 bg-rose-50 hover:bg-rose-100 rounded-lg transition-colors">
            重新提交
          </button>
          <!-- 批改中 -->
          <button v-else disabled
            class="px-4 py-1.5 text-xs font-medium text-gray-400 bg-gray-50 rounded-lg cursor-not-allowed">
            批改中...
          </button>
        </div>
      </div>

      <div v-if="homeworks.length === 0" class="text-center py-8 text-gray-400">
        <BookOpen class="w-10 h-10 mx-auto mb-2 text-gray-200" />
        <p class="text-sm">暂无作业</p>
      </div>
    </div>

    <!-- ===== 作答界面 ===== -->
    <div v-if="answeringHomework" class="space-y-6">
      <!-- 头部 -->
      <div class="flex items-center justify-between">
        <div>
          <h4 class="text-sm font-semibold text-gray-900">{{ answeringHomework.title }}</h4>
          <p v-if="answeringHomework.chapterTitle" class="text-xs text-gray-400">{{ answeringHomework.chapterTitle }}</p>
        </div>
        <button @click="cancelAnswer"
          class="text-xs text-gray-500 hover:text-gray-700 px-3 py-1.5 rounded-lg hover:bg-gray-100">
          返回列表
        </button>
      </div>

      <!-- 题目 -->
      <div v-for="(q, i) in questions" :key="q.id"
        class="border border-gray-200 rounded-xl p-4 space-y-3">
        <div class="flex items-center justify-between">
          <div class="flex items-center gap-2">
            <span class="text-xs font-medium px-2 py-0.5 rounded-full"
              :class="questionTypeClass(q.questionType)">
              {{ questionTypeLabel(q.questionType) }}
            </span>
            <span class="text-xs text-gray-400">{{ q.score }}分</span>
          </div>
          <span v-if="answers[q.id]?.trim()" class="text-xs text-emerald-500">已作答</span>
        </div>

        <p class="text-sm text-gray-900">{{ i + 1 }}. {{ q.questionText }}</p>

        <!-- 选择题 -->
        <div v-if="q.questionType === 'choice'" class="space-y-2 pl-2">
          <label v-for="(opt, oi) in q.options" :key="oi"
            :class="`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-all ${answers[q.id] === opt ? 'border-blue-300 bg-blue-50' : 'border-gray-100 hover:border-gray-200 hover:bg-gray-50'}`">
            <input type="radio" :name="'q-' + q.id" :value="opt"
              :checked="answers[q.id] === opt"
              @change="answers[q.id] = opt"
              class="text-blue-600 focus:ring-blue-500" />
            <span class="text-sm text-gray-700">{{ 'ABCD'[oi] }}. {{ opt }}</span>
          </label>
        </div>

        <!-- 判断题 -->
        <div v-if="q.questionType === 'true_false'" class="flex gap-4 pl-2">
          <label :class="`flex items-center gap-2 px-4 py-2 rounded-lg border cursor-pointer transition-all ${answers[q.id] === '对' ? 'border-green-300 bg-green-50' : 'border-gray-100 hover:border-gray-200'}`">
            <input type="radio" :name="'q-' + q.id" value="对"
              :checked="answers[q.id] === '对'"
              @change="answers[q.id] = '对'"
              class="text-green-600 focus:ring-green-500" />
            <span class="text-sm">对</span>
          </label>
          <label :class="`flex items-center gap-2 px-4 py-2 rounded-lg border cursor-pointer transition-all ${answers[q.id] === '错' ? 'border-red-300 bg-red-50' : 'border-gray-100 hover:border-gray-200'}`">
            <input type="radio" :name="'q-' + q.id" value="错"
              :checked="answers[q.id] === '错'"
              @change="answers[q.id] = '错'"
              class="text-red-600 focus:ring-red-500" />
            <span class="text-sm">错</span>
          </label>
        </div>

        <!-- 填空题 -->
        <div v-if="q.questionType === 'fill'" class="pl-2">
          <input v-model="answers[q.id]" placeholder="请输入答案"
            class="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500" />
        </div>

        <!-- 简答题 -->
        <div v-if="q.questionType === 'short_answer'" class="pl-2">
          <textarea v-model="answers[q.id]" rows="3" placeholder="请输入你的回答"
            class="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"></textarea>
        </div>
      </div>

      <!-- 提交按钮 -->
      <div class="flex items-center gap-3 pt-2">
        <button @click="submitAnswers"
          :disabled="submitting || !allAnswered"
          class="flex-1 py-3 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-xl transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-sm">
          {{ submitting ? '提交批改中...' : '提交作业' }}
        </button>
        <p v-if="!allAnswered" class="text-xs text-amber-500">
          还有 {{ unansweredCount }} 题未作答
        </p>
      </div>
    </div>

    <!-- ===== 查看批改结果 ===== -->
    <div v-if="showResult" class="space-y-6">
      <div class="flex items-center justify-between">
        <div>
          <h4 class="text-sm font-semibold text-gray-900">批改结果</h4>
          <p class="text-xs text-gray-400">{{ resultHomework?.title }}</p>
        </div>
        <div class="text-right">
          <p class="text-2xl font-bold" :class="getScoreColor(resultData?.totalScore || 0)">{{ resultData?.totalScore || 0 }}<span class="text-sm text-gray-400"> / {{ resultData?.maxScore || 100 }}</span></p>
          <p class="text-xs text-gray-400">得分</p>
        </div>
      </div>

      <div v-for="(q, i) in resultData?.questions || []" :key="q.id"
        class="border rounded-xl p-4"
        :class="q.isCorrect ? 'border-green-200 bg-green-50/50' : 'border-red-200 bg-red-50/50'">
        <div class="flex items-center justify-between mb-2">
          <div class="flex items-center gap-2">
            <span class="text-xs font-medium px-2 py-0.5 rounded-full"
              :class="questionTypeClass(q.questionType)">
              {{ questionTypeLabel(q.questionType) }}
            </span>
            <span class="text-xs text-gray-400">{{ q.score }}分</span>
          </div>
          <span :class="`text-xs font-medium px-2 py-0.5 rounded-full ${q.isCorrect ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`">
            {{ q.isCorrect ? '✓ 正确' : '✗ 错误' }}
            <span class="text-gray-400 ml-1">得{{ q.studentScore }}分</span>
          </span>
        </div>
        <p class="text-sm text-gray-900 mb-2">{{ i + 1 }}. {{ q.questionText }}</p>

        <div class="space-y-1 text-sm">
          <p class="text-gray-600">你的答案：<span :class="q.isCorrect ? 'text-green-600' : 'text-red-600'">{{ q.studentAnswer || '(未作答)' }}</span></p>
          <p class="text-gray-600">正确答案：<span class="text-emerald-600">{{ q.answer }}</span></p>
          <p v-if="q.aiFeedback" class="text-xs text-gray-500 mt-2 bg-white rounded-lg p-2 border border-gray-100">{{ q.aiFeedback }}</p>
        </div>
      </div>

      <!-- 进度条 -->
      <div class="bg-white rounded-xl border border-gray-100 p-4">
        <p class="text-xs text-gray-500 mb-2">答题情况</p>
        <div class="flex gap-1">
          <div v-for="(q, i) in resultData?.questions || []" :key="i"
            class="flex-1 h-2 rounded-full"
            :class="q.isCorrect ? 'bg-green-400' : 'bg-red-400'"
            :title="`第${i+1}题 ${q.isCorrect ? '正确' : '错误'}`">
          </div>
        </div>
        <p class="text-xs text-gray-400 mt-2">
          正确 {{ correctCount }}/{{ resultData?.questions?.length || 0 }} 题
        </p>
      </div>

      <button @click="closeResult"
        class="w-full py-2.5 text-sm text-gray-600 bg-gray-50 hover:bg-gray-100 rounded-xl transition-colors">
        返回作业列表
      </button>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, computed, onMounted, watch } from 'vue'
import { BookOpen } from 'lucide-vue-next'
import { API_BASE } from '@/api'

const props = defineProps<{ courseId: string; studentId: string; tier?: string }>()

const API = `${API_BASE}/homeworks`

// ====== 状态 ======
const homeworks = ref<any[]>([])
const answeringHomework = ref<any>(null)
const questions = ref<any[]>([])
const answers = ref<Record<string, string>>({})
const submitting = ref(false)
const showResult = ref(false)
const resultData = ref<any>(null)
const resultHomework = ref<any>(null)

onMounted(async () => {
  // 先查学生的层级，再拉作业（避免层级未就绪时拿到所有3套）
  await fetchStudentTier()
  loadHomeworks()
})

// tier prop 变化时也重新拉（兜底）
watch(() => props.tier, () => { loadHomeworks() })

// 从后端获取该学生在这门课的层级
const studentTier = ref('')
async function fetchStudentTier() {
  if (!props.studentId) return
  try {
    const res = await fetch(`${API_BASE}/tier-test/${props.courseId}/result/${props.studentId}`)
    const data = await res.json()
    if (data.success && data.result) {
      studentTier.value = data.result.tier
    }
  } catch (e) { /* 网络错误忽略，默认不过滤 */ }
}

// ====== 计算属性 ======
const submittedCount = computed(() =>
  homeworks.value.filter(h => h.submission?.status === 'graded').length
)

const allAnswered = computed(() =>
  questions.value.every(q => answers.value[q.id]?.trim())
)

const unansweredCount = computed(() =>
  questions.value.filter(q => !answers.value[q.id]?.trim()).length
)

const correctCount = computed(() =>
  resultData.value?.questions?.filter((q: any) => q.isCorrect).length || 0
)

// ====== 加载作业列表 ======
async function loadHomeworks() {
  try {
    // 优先用本地查到的层级，其次用父组件传入的
    const tier = studentTier.value || props.tier || ''
    const tierParam = tier ? `&tier=${tier}` : ''
    const res = await fetch(`${API}/student/${props.courseId}?studentId=${props.studentId}${tierParam}`)
    const data = await res.json()
    if (data.success) homeworks.value = data.homeworks
  } catch (e) { console.error('加载作业列表失败:', e) }
}

// ====== 开始作答 ======
async function startAnswer(hw: any) {
  try {
    const res = await fetch(`${API}/student/view/${hw.id}`)
    const data = await res.json()
    if (data.success) {
      answeringHomework.value = data.homework
      questions.value = data.homework.questions
      answers.value = {}
    }
  } catch (e) { console.error('加载作业题目失败:', e) }
}

function retryAnswer(hw: any) {
  startAnswer(hw)
}

function cancelAnswer() {
  answeringHomework.value = null
  questions.value = []
  answers.value = {}
}

// ====== 提交答案 ======
async function submitAnswers() {
  if (!allAnswered.value) return
  submitting.value = true

  try {
    const answerList = Object.entries(answers.value).map(([questionId, answerText]) => ({
      questionId,
      answerText,
    }))

    const res = await fetch(`${API}/${answeringHomework.value.id}/submit`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ studentId: props.studentId, answers: answerList }),
    })
    const data = await res.json()

    if (data.success) {
      // 直接显示批改结果
      await loadResult(answeringHomework.value.id)
      answeringHomework.value = null
      questions.value = []
      answers.value = {}
      loadHomeworks()
    } else {
      await loadHomeworks()
      alert('提交失败：' + data.message)
    }
  } catch (e: any) {
    await loadHomeworks()
    alert('提交失败：' + e.message)
  } finally {
    submitting.value = false
  }
}

// ====== 查看结果 ======
async function viewResult(hw: any) {
  await loadResult(hw.id)
  resultHomework.value = hw
}

async function loadResult(homeworkId: string) {
  try {
    const res = await fetch(`${API}/${homeworkId}/result/${props.studentId}`)
    const data = await res.json()
    if (data.success) {
      resultData.value = data.result
      showResult.value = true
    }
  } catch (e) { console.error('加载批改结果失败:', e) }
}

function closeResult() {
  showResult.value = false
  resultData.value = null
  resultHomework.value = null
}

// ====== 工具函数 ======
function getScoreClass(score: number) {
  if (score >= 80) return 'text-emerald-600 bg-emerald-50'
  if (score >= 60) return 'text-amber-600 bg-amber-50'
  return 'text-red-600 bg-red-50'
}

function getScoreColor(score: number) {
  if (score >= 80) return 'text-emerald-600'
  if (score >= 60) return 'text-amber-600'
  return 'text-red-600'
}

function questionTypeLabel(type: string) {
  const map: Record<string, string> = {
    choice: '选择题',
    true_false: '判断题',
    fill: '填空题',
    short_answer: '简答题',
  }
  return map[type] || type
}

function questionTypeClass(type: string) {
  const map: Record<string, string> = {
    choice: 'bg-blue-50 text-blue-600',
    true_false: 'bg-purple-50 text-purple-600',
    fill: 'bg-amber-50 text-amber-600',
    short_answer: 'bg-emerald-50 text-emerald-600',
  }
  return map[type] || 'bg-gray-50 text-gray-600'
}
</script>
